#!/usr/bin/env node
// ADR-0009: each project's deployed file is a committed bundle of the files in its list
// deploy/<name>.files (3.9.2, tools/projects.js; e.g. deploy/mailtodrive.files → MailToDrive.gs). One implementation; runall checks
// that the committed file equals a fresh build (`--check`), so a stale or hand-edited bundle cannot pass CI.
// Usage: node tools/bundle.js            write every project's bundle (deploy/*.files, tools/projects.js)
//        node tools/bundle.js --check    exit 1 when any committed bundle differs from a fresh build
'use strict';
const fs = require('fs'), path = require('path'), vm = require('vm');
const { projects, moduleOrder } = require('./projects');
const D = path.resolve(__dirname, '..');
const depsOf = (root, m) => { const f = path.join(root, 'modules', m, 'CONTRACT.md'); if (!fs.existsSync(f)) return [];
  const t = fs.readFileSync(f, 'utf8'), r = /^## Depends on[^\n]*\n([\s\S]*?)(?=^## |(?![\s\S]))/m.exec(t); return r ? r[1].trim().split(/[,\s]+/).filter(x => /^[A-Z]\w+$/.test(x)) : []; };
// build(root, list?) → the bundle text for one project list (default: the project that builds at the repo root; 3.10.0).
function build(root, LIST) {
  if (!LIST) { const r = projects(root).find(p => !p.out.includes('/')); if (!r) throw new Error('no project builds at the repo root; pass a list'); LIST = r.list; }
  const files = fs.readFileSync(path.join(root, LIST), 'utf8').split('\n').map(l => l.trim()).filter(l => l && !l.startsWith('#'));
  const last = files[files.length - 1] || '';
  if (!files.length || last.startsWith('modules/') || !/^([a-z]+\/)?src\/[A-Za-z.]+\.gs$/.test(last)) throw new Error(LIST + ': the project file must be listed last');
  const seen = new Set(), parts = ['// GENERATED by tools/bundle.js from ' + LIST + ' — do not edit. Edit src/ or modules/, then run: node tools/bundle.js\n'];
  for (const f of files) {
    if (seen.has(f)) throw new Error(LIST + ': ' + f + ' listed twice');
    seen.add(f);
    if (!/^(([a-z]+\/)?src|modules\/[A-Za-z]+)\/[A-Za-z.]+\.gs$/.test(f)) throw new Error(LIST + ': ' + f + ' is not under src/, <dir>/src/ or modules/<Name>/');
    const buf = fs.readFileSync(path.join(root, f));
    if (buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) throw new Error(f + ': has a BOM');
    const text = buf.toString('utf8');
    if (!Buffer.from(text, 'utf8').equals(buf)) throw new Error(f + ': is not valid UTF-8');                 // review 1a L3
    try { new vm.Script(text, { filename: f }); } catch (e) { throw new Error(f + ': does not parse on its own (' + e.message + ')'); }   // review 1a L2: an open /* would swallow the next file
    if (text.includes('\r')) throw new Error(f + ': has CR (Windows) line endings');
    if (!text.endsWith('\n')) throw new Error(f + ': must end with a newline');
    if (/^\s*['"]use strict['"]/m.test(text)) throw new Error(f + ": contains 'use strict' (would change every file after it in the bundle)");
    parts.push(';\n// ===== file: ' + f + ' =====\n', text);          // ';' ends any statement left open by the file before
  }
  // 3.9.2 (Phase 2 §10): modules are a subsequence of deploy/modules.order, each listed after its Depends-on modules.
  // Which modules a project must list (exactly the ones it uses + their dependencies) is checked by tools/guards.js (AST).
  const order = moduleOrder(root), mods = files.filter(f => f.startsWith('modules/')).map(f => f.split('/')[1]);
  for (const m of mods) {
    if (files.indexOf('modules/' + m + '/' + m + '.gs') < 0) throw new Error(LIST + ': list modules as modules/<Name>/<Name>.gs (' + m + ')');
    if (!order.includes(m)) throw new Error(LIST + ': modules/' + m + ' is not in deploy/modules.order');
    for (const d of depsOf(root, m)) if (!mods.includes(d) || mods.indexOf(d) > mods.indexOf(m)) throw new Error(LIST + ': ' + m + ' depends on ' + d + ', which must be listed before it');
  }
  for (let i = 1; i < mods.length; i++) if (order.indexOf(mods[i - 1]) > order.indexOf(mods[i])) throw new Error(LIST + ': ' + mods[i] + ' is listed after ' + mods[i - 1] + ' (registry order: deploy/modules.order)');
  const dir = path.join(root, 'modules');                                                                      // review 1a L5: every landed module is registered
  for (const m of fs.existsSync(dir) ? fs.readdirSync(dir) : []) if (fs.existsSync(path.join(dir, m, m + '.gs')) && !order.includes(m)) throw new Error('modules/' + m + '/' + m + '.gs exists but is not in deploy/modules.order');
  return parts.join('');
}
if (require.main === module) {
  const all = projects(D), check = process.argv.includes('--check');
  let bad = 0;
  for (const p of all) {
    const out = build(D, p.list), file = path.join(D, p.out);
    if (check) { const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
      if (cur !== out) { console.log('STALE ' + p.out + ' differs from a fresh build of ' + p.list + ' (run node tools/bundle.js)'); bad++; } else console.log('OK ' + p.out + ' = fresh build'); }
    else { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, out); console.log('wrote ' + p.out + ' (' + out.length + ' chars)'); }
  }
  if (!all.length) { console.log('no deploy/*.files project lists'); process.exit(1); }
  process.exit(bad ? 1 : 0);
}
module.exports = { build };
